import { Modal, Box, IconButton } from '@mui/material';
import CloseIcon from '@mui/icons-material/Close';
import PhotoViewer from './PhotoViewer';

const PointOfInterest = ({open, onClose, data}) => {
	return (
		<Modal 
			open={open}
			onClose={onClose}
			sx={{
				display: 'flex',
				//alignItems: 'center',
				justifyContent: 'center',
				padding: '20px', // Adjust for spacing from edges
			}}
		>
			<Box sx={{
				//width: '80vw', // Adjust the width as needed
				//height: '80vh', // Adjust the height as needed
				maxWidth: '90vw',
				maxHeight: '90vh',
				width: '80vw',
				height: '80vh',
				bgcolor: 'background.paper',
				borderRadius: 2,
				boxShadow: 24,
				//p: 4,
				//overflow: 'auto',
				overflow: 'hidden',
				p: 2,
				inset: 0,
				alignItems: 'center',
				//position: 'relative',
				position: 'absolute',
				margin: 'auto',
				/*
				"& .image-gallery": {
					//height: "100%",
					//width: '80vw',
					height: '80vh'
				},
				"& .image-gallery-content": {
					//width: '80vw',
					height: '80vh'
				},
				"& .image-gallery-slide-wrapper": {
					height: "auto",
					//width: "auto"
				},
				"& .image-gallery-slide img": {
					//maxHeight: "100%",
					//maxWidth: "100%",
					maxHeight: "80vh",
					maxWidth: "80vw",
					objectFit: "contain",
				}
				*/
				"& .image-gallery-slide img": {
					maxHeight: "90vh",
					maxWidth: "90vw",
					objectFit: "contain",
				}
			}}>
				<Box>
					sx={{
						width: "90vw",
						height: "90vh",
						display: "flex",
						flexDirection: "column",
						overflow: "hidden",
					}}
				</Box>
				<Box sx={{ flexShrink: 0 }}>
					{
						data.title 
							? 
								<div>
									<h2>{data.title ? data.title : "Placeholder"}</h2>
									<p>{data.description ? data.description : "Placeholder"}</p>
								</div>
							: 
								<div>
									<h2>{data.label ? data.label : "Placeholder"}</h2>
									<p>{data.details.description ? data.details.description : "Placeholder"}</p>
								</div>
					}
				</Box>
				<Box sx={{
					flexGrow: 1,
					minHeight: 0
				}}>
					<PhotoViewer items={data.images} />
				</Box>
			</Box>
		</Modal>
	)
}

export default PointOfInterest;